import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

interface Webhook {
  type: number;
  schema: string;
  eventType?: string;
}

const HEADER = `// <auto-generated>
// Code generated by scripts/render-events.ts from the OpenAPI spec. DO NOT EDIT.
// </auto-generated>
#nullable enable
`;

/** The event class for a webhook schema: `OrderStatusChangeWebhook` becomes `OrderStatusChangeEvent`. */
export function eventClass(schema: string): string {
  if (!schema.endsWith('Webhook')) throw new Error(`webhook schema ${schema} does not end in "Webhook"`);
  return `${schema.slice(0, -'Webhook'.length)}Event`;
}

/**
 * Write, into `<dir>`:
 *  - `Events/<Name>Event.cs`: one sealed class per webhook, in namespace `TikTokShop.Api`, extending the hand-written
 *    `WebhookEvent`, with a typed `Payload` holding the generated model;
 *  - `WebhookEvents.cs`: the internal type to event dispatch used by `Webhooks.Parse`.
 */
export function renderEvents(metaPath: string, dir: string): void {
  const hooks = (JSON.parse(readFileSync(metaPath, 'utf8')) as { webhooks: Webhook[] }).webhooks
    .slice()
    .sort((a, b) => a.type - b.type);
  const models = new Set(readdirSync(join(dir, 'Model')).map((f) => f.replace(/\.cs$/, '')));
  const events = join(dir, 'Events');
  mkdirSync(events, { recursive: true });

  const names = new Set<string>();
  const types = new Set<number>();
  for (const w of hooks) {
    const cls = eventClass(w.schema);
    if (names.has(cls)) throw new Error(`two webhooks render to the event class ${cls}`);
    if (types.has(w.type)) throw new Error(`two webhooks have the type ${w.type}`);
    if (!models.has(w.schema)) throw new Error(`no generated model ${w.schema}`);
    if (models.has(cls) || cls === 'WebhookEvent') throw new Error(`event class ${cls} collides with a generated model`);
    names.add(cls);
    types.add(w.type);
    writeFileSync(
      join(events, `${cls}.cs`),
      `${HEADER}using System;
using Newtonsoft.Json.Linq;
using TikTokShop.Api.Generated.Model;

namespace TikTokShop.Api;

/// <summary>A webhook of type ${w.type}${w.eventType ? ` (${w.eventType})` : ''}.</summary>
public sealed class ${cls} : WebhookEvent
{
    /// <summary>The webhook <c>type</c> this event is for.</summary>
    public const int TypeCode = ${w.type};

    /// <summary>Creates the event.</summary>
    public ${cls}(${w.schema} payload, JObject raw)
        : base(TypeCode, raw)
    {
        Payload = payload ?? throw new ArgumentNullException(nameof(payload));
    }

    /// <summary>The parsed body.</summary>
    public ${w.schema} Payload { get; }
}
`,
    );
  }

  const arms = hooks.map((w) => `        ${w.type} => new ${eventClass(w.schema)}(Payload<${w.schema}>(raw, serializer), raw),`);
  writeFileSync(
    join(dir, 'WebhookEvents.cs'),
    `${HEADER}using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using TikTokShop.Api.Generated.Model;

namespace TikTokShop.Api;

/// <summary>Maps a webhook <c>type</c> to its event class. Use <see cref="Webhooks.Parse(string)"/>, which checks the body first.</summary>
internal static class WebhookEvents
{
    /// <summary>The event for <paramref name="type"/>, or <c>null</c> when this SDK does not know the type. Throws on a body its model rejects.</summary>
    internal static WebhookEvent? Create(int type, JObject raw, JsonSerializer serializer) => type switch
    {
${arms.join('\n')}
        _ => null,
    };

    private static T Payload<T>(JObject raw, JsonSerializer serializer)
        where T : class =>
        raw.ToObject<T>(serializer) ?? throw new JsonSerializationException("the body is null");
}
`,
  );
}
